function isKeyboardAccessible(el) {
  const NATIVE = new Set(['button', 'input', 'select', 'textarea']);
  if (NATIVE.has(el.tag)) return true;
  if (el.tag === 'a') return typeof el.href === 'string' && el.href.length > 0;
  return el.tabIndex === 0 && el.hasKeyHandler === true;
}

function auditElements(elements) {
  return elements.filter((el) => !isKeyboardAccessible(el)).length;
}

function semanticTagFor(role) {
  const MAP = {
    'primary-action': 'button',
    'internal-link': 'a',
    'external-link': 'a',
    'page-heading': 'h1',
    'top-navigation': 'nav',
    'main-content': 'main',
  };
  return MAP[role] || 'div';
}

