function refactorPage(elements) {
  return elements.map((el) => ({ tag: semanticTagFor(el.role), text: el.text }));
}

function semanticTagFor(role) {
  const MAP = {
    'primary-action': 'button',
    'internal-link': 'a',
    'external-link': 'a',
    'page-heading': 'h1',
    'top-navigation': 'nav',
    'main-content': 'main',
  };
  return MAP[role] || 'div';
}

function countMisusedDivs(elements) {
  return elements.filter((el) => {
    const expected = semanticTagFor(el.role);
    return expected !== 'div' && el.tag === 'div';
  }).length;
}

function hasSkippedHeadingLevel(levels) {
  for (let i = 1; i < levels.length; i++) {
    if (levels[i] > levels[i - 1] && levels[i] - levels[i - 1] > 1) {
      return true;
    }
  }
  return false;
}

function firstSkippedHeadingIndex(levels) {
  for (let i = 1; i < levels.length; i++) {
    if (levels[i] > levels[i - 1] && levels[i] - levels[i - 1] > 1) {
      return i;
    }
  }
  return -1;
}

function deepestHeadingLevel(levels) {
  if (levels.length === 0) return 0;
  return Math.max(...levels);
}

function countLandmarks(tags) {
  const LANDMARKS = new Set(['header', 'nav', 'main', 'footer', 'aside']);
  return tags.filter((t) => LANDMARKS.has(t)).length;
}

function missingLandmarks(tags) {
  const ORDER = ['header', 'nav', 'main', 'footer', 'aside'];
  const present = new Set(tags);
  return ORDER.filter((t) => !present.has(t));
}

function isFullyAccessibleInteractiveDiv(el) {
  if (el.tag !== 'div' && el.tag !== 'span') return true;
  return el.role === 'button' && el.tabIndex === 0 && el.hasKeyHandler === true;
}
